        let len = body.len();
        let resp = format!(
            "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {len}\r\nConnection: close\r\n\r\n{body}"
        );
        let _ = stream.write_all(resp.as_bytes());
    }
}

